import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_layernorm_cuda_src = r"""
   #include <torch/extension.h>
   #include <cuda.h>
   #include <cuda_runtime.h>
   #include <ATen/cuda/CUDAContext.h>
   extern "C" __global__
   void layernorm_reduce_rows_kernel(const float* __restrict__ x,
                                     long n_rows,
                                     long row_size,
                                     long blocks_per_row,
                                     double* __restrict__ sums,
                                     double* __restrict__ sumsq) {
       long row = blockIdx.x;
       long tile = blockIdx.y;
       if (row >= n_rows) return;
       long start = row * row_size;
       long tile_elems = (row_size + blocks_per_row - 1) / blocks_per_row;
       long tile_start = tile * tile_elems;
       if (tile_start >= row_size) return;
       long tile_end = ((tile_start + tile_elems) < row_size) ? (tile_start + tile_elems) : row_size;
       extern __shared__ double smem[]; // size 2*blockDim.x doubles
       double* s_sum = smem;
       double* s_sumsq = smem + blockDim.x;
       double local_sum = 0.0;
       double local_sumsq = 0.0;
       const float* x_row = x + start;
       long first_aligned = (tile_start + 3L) & ~3L; // ceil to multiple of 4
       if (first_aligned > tile_end) first_aligned = tile_end;
       // Prologue: scalar until alignment
       for (long idx = tile_start + threadIdx.x; idx < first_aligned; idx += blockDim.x) {
           float v = x_row[idx];
           double vd = (double)v;
           local_sum += vd;
           local_sumsq += vd * vd;
       }
       // Main: vectorized float4
       long vec_elems = tile_end - first_aligned;
       long vec_chunks = vec_elems >> 2; // /4
       if (vec_chunks > 0) {
           const float4* __restrict__ x4 = reinterpret_cast<const float4*>(x_row + first_aligned);
           for (long c = threadIdx.x; c < vec_chunks; c += blockDim.x) {
               float4 v4 = x4[c];
               double a = (double)v4.x; local_sum += a; local_sumsq += a * a;
               double b = (double)v4.y; local_sum += b; local_sumsq += b * b;
               double c2 = (double)v4.z; local_sum += c2; local_sumsq += c2 * c2;
               double d = (double)v4.w; local_sum += d; local_sumsq += d * d;
           }
       }
       // Epilogue: scalar tail
       long last_aligned = first_aligned + (vec_chunks << 2);
       for (long idx = last_aligned + threadIdx.x; idx < tile_end; idx += blockDim.x) {
           float v = x_row[idx];
           double vd = (double)v;
           local_sum += vd;
           local_sumsq += vd * vd;
       }
       s_sum[threadIdx.x] = local_sum;
       s_sumsq[threadIdx.x] = local_sumsq;
       __syncthreads();
       for (unsigned int s = blockDim.x >> 1; s > 0; s >>= 1) {
           if (threadIdx.x < s) {
               s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
               s_sumsq[threadIdx.x] += s_sumsq[threadIdx.x + s];
           }
           __syncthreads();
       }
       if (threadIdx.x == 0) {
           atomicAdd(&sums[row], s_sum[0]);
           atomicAdd(&sumsq[row], s_sumsq[0]);
       }
   }
   extern "C" __global__
   void layernorm_apply_kernel(const float* __restrict__ x,
                               const float* __restrict__ gamma,
                               const float* __restrict__ beta,
                               float* __restrict__ y,
                               long n_rows,
                               long row_size,
                               long blocks_per_row,
                               double eps,
                               const double* __restrict__ sums,
                               const double* __restrict__ sumsq) {
       long row = blockIdx.x;
       long tile = blockIdx.y;
       if (row >= n_rows) return;
       long start = row * row_size;
       long tile_elems = (row_size + blocks_per_row - 1) / blocks_per_row;
       long tile_start = tile * tile_elems;
       if (tile_start >= row_size) return;
       long tile_end = ((tile_start + tile_elems) < row_size) ? (tile_start + tile_elems) : row_size;
       double mean = sums[row] / (double)row_size;
       double ex2 = sumsq[row] / (double)row_size;
       double var = ex2 - mean * mean;
       if (var < 0.0) var = 0.0;
       double inv_std = rsqrt(var + eps);
       const float* x_row = x + start;
       float* y_row = y + start;
       long first_aligned = (tile_start + 3L) & ~3L; // ceil to multiple of 4
       if (first_aligned > tile_end) first_aligned = tile_end;
       // Prologue: scalar until alignment
       for (long idx = tile_start + threadIdx.x; idx < first_aligned; idx += blockDim.x) {
           float v = x_row[idx];
           float norm = (float)(((double)v - mean) * inv_std);
           if (gamma != nullptr) {
               norm = norm * gamma[idx];
           }
           if (beta != nullptr) {
               norm = norm + beta[idx];
           }
           y_row[idx] = norm;
       }
       // Main: vectorized float4
       long vec_elems = tile_end - first_aligned;
       long vec_chunks = vec_elems >> 2; // /4
       if (vec_chunks > 0) {
           const float4* __restrict__ x4 = reinterpret_cast<const float4*>(x_row + first_aligned);
           float4* __restrict__ y4 = reinterpret_cast<float4*>(y_row + first_aligned);
           const float4* __restrict__ g4 = (gamma != nullptr) ? reinterpret_cast<const float4*>(gamma + first_aligned) : nullptr;
           const float4* __restrict__ b4 = (beta != nullptr) ? reinterpret_cast<const float4*>(beta + first_aligned) : nullptr;
           for (long c = threadIdx.x; c < vec_chunks; c += blockDim.x) {
               float4 vx = x4[c];
               float4 out;
               if (g4 != nullptr && b4 != nullptr) {
                   float4 gg = g4[c];
                   float4 bb = b4[c];
                   out.x = (float)(((double)vx.x - mean) * inv_std) * gg.x + bb.x;
                   out.y = (float)(((double)vx.y - mean) * inv_std) * gg.y + bb.y;
                   out.z = (float)(((double)vx.z - mean) * inv_std) * gg.z + bb.z;
                   out.w = (float)(((double)vx.w - mean) * inv_std) * gg.w + bb.w;
               } else if (g4 != nullptr) {
                   float4 gg = g4[c];
                   out.x = (float)(((double)vx.x - mean) * inv_std) * gg.x;
                   out.y = (float)(((double)vx.y - mean) * inv_std) * gg.y;
                   out.z = (float)(((double)vx.z - mean) * inv_std) * gg.z;
                   out.w = (float)(((double)vx.w - mean) * inv_std) * gg.w;
               } else if (b4 != nullptr) {
                   float4 bb = b4[c];
                   out.x = (float)(((double)vx.x - mean) * inv_std) + bb.x;
                   out.y = (float)(((double)vx.y - mean) * inv_std) + bb.y;
                   out.z = (float)(((double)vx.z - mean) * inv_std) + bb.z;
                   out.w = (float)(((double)vx.w - mean) * inv_std) + bb.w;
               } else {
                   out.x = (float)(((double)vx.x - mean) * inv_std);
                   out.y = (float)(((double)vx.y - mean) * inv_std);
                   out.z = (float)(((double)vx.z - mean) * inv_std);
                   out.w = (float)(((double)vx.w - mean) * inv_std);
               }
               y4[c] = out;
           }
       }
       // Epilogue: scalar tail
       long last_aligned = first_aligned + (vec_chunks << 2);
       for (long idx = last_aligned + threadIdx.x; idx < tile_end; idx += blockDim.x) {
           float v = x_row[idx];
           float norm = (float)(((double)v - mean) * inv_std);
           if (gamma != nullptr) {
               norm = norm * gamma[idx];
           }
           if (beta != nullptr) {
               norm = norm + beta[idx];
           }
           y_row[idx] = norm;
       }
   }
   torch::Tensor layernorm_forward(torch::Tensor x,
                                   c10::optional<torch::Tensor> gamma_opt,
                                   c10::optional<torch::Tensor> beta_opt,
                                   int64_t n_rows,
                                   int64_t row_size,
                                   double eps) {
       TORCH_CHECK(x.is_cuda(), "Input x must be on CUDA");
       TORCH_CHECK(x.scalar_type() == at::kFloat, "Only float32 is supported");
       auto x_contig = x.contiguous();
       const float* gamma_ptr = nullptr;
       const float* beta_ptr = nullptr;
       torch::Tensor gamma, beta;
       if (gamma_opt.has_value()) {
           gamma = gamma_opt.value();
           TORCH_CHECK(gamma.is_cuda(), "gamma must be on CUDA");
           TORCH_CHECK(gamma.scalar_type() == at::kFloat, "gamma must be float32");
           TORCH_CHECK(gamma.numel() == row_size, "gamma numel must equal row_size");
           gamma_ptr = gamma.contiguous().data_ptr<float>();
       }
       if (beta_opt.has_value()) {
           beta = beta_opt.value();
           TORCH_CHECK(beta.is_cuda(), "beta must be on CUDA");
           TORCH_CHECK(beta.scalar_type() == at::kFloat, "beta must be float32");
           TORCH_CHECK(beta.numel() == row_size, "beta numel must equal row_size");
           beta_ptr = beta.contiguous().data_ptr<float>();
       }
       TORCH_CHECK(x_contig.numel() == n_rows * row_size, "x.numel() must equal n_rows * row_size");
       auto y = torch::empty_like(x_contig);
        int threads = 256;
        dim3 block(threads);
        // Choose tile_elems to create enough blocks per row.
        const int64_t tile_elems = 4096; // 16 elements per thread for 256-thread blocks
        int64_t blocks_per_row = (row_size + tile_elems - 1) / tile_elems;
        if (blocks_per_row < 1) blocks_per_row = 1;
        if (blocks_per_row > 65535) blocks_per_row = 65535;
        dim3 grid_reduce((unsigned int)n_rows, (unsigned int)blocks_per_row, 1);
        size_t shmem = 2 * threads * sizeof(double);
        // Workspace for per-row sums
        auto options = torch::TensorOptions().dtype(torch::kFloat64).device(x.device());
        auto sums = torch::zeros({n_rows}, options);
        auto sumsq = torch::zeros({n_rows}, options);
        const float* x_ptr = x_contig.data_ptr<float>();
        float* y_ptr = y.data_ptr<float>();
        double* sums_ptr = sums.data_ptr<double>();
        double* sumsq_ptr = sumsq.data_ptr<double>();
        cudaStream_t stream = at::cuda::getCurrentCUDAStream().stream();
        layernorm_reduce_rows_kernel<<<grid_reduce, block, shmem, stream>>>(
            x_ptr,
            (long)n_rows,
            (long)row_size,
            (long)blocks_per_row,
            sums_ptr,
            sumsq_ptr
        );
        auto err = cudaGetLastError();
        TORCH_CHECK(err == cudaSuccess, "CUDA kernel launch failed (reduce): ", cudaGetErrorString(err));
        dim3 grid_apply((unsigned int)n_rows, (unsigned int)blocks_per_row, 1);
        size_t shmem_apply = 0;
        layernorm_apply_kernel<<<grid_apply, block, shmem_apply, stream>>>(
            x_ptr,
            gamma_ptr,
            beta_ptr,
            y_ptr,
            (long)n_rows,
            (long)row_size,
            (long)blocks_per_row,
            eps,
            (const double*)sums_ptr,
            (const double*)sumsq_ptr
        );
        err = cudaGetLastError();
        TORCH_CHECK(err == cudaSuccess, "CUDA kernel launch failed (apply): ", cudaGetErrorString(err));
        return y;
   }
   """

_layernorm_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor layernorm_forward(torch::Tensor x,
                                c10::optional<torch::Tensor> gamma_opt,
                                c10::optional<torch::Tensor> beta_opt,
                                int64_t n_rows,
                                int64_t row_size,
                                double eps);
"""
_layernorm_ext = load_inline(
    name="layernorm_cuda_ext",
    cpp_sources=[_layernorm_cpp_decl],
    cuda_sources=[_layernorm_cuda_src],
    functions=["layernorm_forward"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple, eps: float = 1e-5, elementwise_affine: bool = True) -> None:
        super().__init__()
        if isinstance(normalized_shape, int):
            normalized_shape = (normalized_shape,)
        self.normalized_shape = tuple(normalized_shape)
        self.eps = float(eps)
        self.elementwise_affine = elementwise_affine
        if self.elementwise_affine:
            self.weight = nn.Parameter(torch.ones(self.normalized_shape, dtype=torch.float32))
            self.bias = nn.Parameter(torch.zeros(self.normalized_shape, dtype=torch.float32))
        else:
            self.register_parameter("weight", None)
            self.register_parameter("bias", None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be on CUDA"
        x = x.contiguous()
        # Compute row_size as product of normalized_shape, n_rows as remaining
        row_size = 1
        for d in self.normalized_shape:
            row_size *= int(d)
        total = x.numel()
        assert total % row_size == 0, "Input shape is incompatible with normalized_shape"
        n_rows = total // row_size

        gamma = None
        beta = None
        if self.elementwise_affine:
            # Ensure parameters are on same device and dtype
            assert self.weight.numel() == row_size, "Weight shape mismatch with normalized_shape"
            assert self.bias.numel() == row_size, "Bias shape mismatch with normalized_shape"
            if self.weight.device != x.device:
                gamma = self.weight.to(device=x.device, dtype=torch.float32)
            else:
                gamma = self.weight
            if self.bias.device != x.device:
                beta = self.bias.to(device=x.device, dtype=torch.float32)
            else:
                beta = self.bias

        # Enforce dtype float32 for kernel
        if x.dtype != torch.float32:
            x_in = x.to(dtype=torch.float32)
        else:
            x_in = x

        y = _layernorm_ext.layernorm_forward(x_in, gamma, beta, int(n_rows), int(row_size), float(self.eps))

        # Cast back to original dtype if needed
        if y.dtype != x.dtype:
            y = y.to(dtype=x.dtype)
        # Reshape is same as input since we operated in-place layout-preserving
        return y

