               s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
               s_sumsq[threadIdx.x] += s_sumsq[threadIdx.x + s];
           }
           __syncthreads();
       }

       if (threadIdx.x == 0) {
           atomicAdd(&sums[row], s_sum[0]);
           atomicAdd(&sumsq[row], s_sumsq[0]);
       }
   }

